    fail_critical: bool,
}

#[derive(Serialize, Debug, Clone)]
struct JsonSummary {
    total: usize,
    errors: usize,
    warnings: usize,
    passed: usize,
}

#[derive(Serialize, Debug, Clone)]
struct JsonResult {
    id: String,
    severity: String,
    message: String,
    file: String,
    line: usize,
    #[serde(skip_serializing_if = "Option::is_none")]
    suggestion: Option<String>,
}

#[derive(Serialize, Debug, Clone)]
struct JsonOutput {
    version: String,
    timestamp: String,
    summary: JsonSummary,
    results: Vec<JsonResult>,
}

fn main() -> Result<()> {
    // Determine if json format is active via --format json or --json flag
    let args = Cli::parse();
    let is_json = args.json || args.format == "json";

    if !is_json {
        tracing_subscriber::fmt()
            .with_env_filter("sandbox_ffi_layers=info")
            .init();
    }

    if args.check {
        let content = std::fs::read_to_string(&args.lockfile)?;
        let packages = cargo_lock::parse_cargo_lock(&content)?;
        let surfaces = cargo_lock::analyze_native_surface(&packages);

        if !is_json {
            tracing::info!(
                "Analyzed {} packages, {} have native build surface",
                packages.len(),
                surfaces.len()
            );

            for surface in &surfaces {
                let risk = if surface.has_proc_macro {
                    "PROC-MACRO"
                } else {
                    "BUILD"
                };
                println!(
                    "  [{}] {}@{} — {}",
                    risk,
                    surface.package.name,
                    surface.package.version,
                    if surface.has_proc_macro {
                        "proc-macro crate"
                    } else {
                        "build script dep"
                    }
                );
            }
        }

        // Check for known-malicious patterns (proc-macro1 == typosquat)
        let malicious: Vec<_> = packages
            .iter()
            .filter(|p| p.name == "proc-macro1" || p.name == "proc-macro-en")
            .collect();

        if is_json {
            let mut results = Vec::new();
            for m in &malicious {
                results.push(JsonResult {
                    id: "known-malicious-package".to_string(),
                    severity: "error".to_string(),
                    message: format!("Known malicious or typosquat package detected: {}@{}", m.name, m.version),
                    file: args.lockfile.clone(),
                    line: 0,
                    suggestion: Some("Remove or replace this dependency immediately.".to_string()),
                });
            }

            for surface in &surfaces {
                let severity = if surface.has_proc_macro { "warning" } else { "info" };
                let msg = if surface.has_proc_macro {
                    format!("Proc-macro crate detected: {}@{}", surface.package.name, surface.package.version)
                } else {
                    format!("Native build surface detected: {}@{}", surface.package.name, surface.package.version)
                };
                results.push(JsonResult {
                    id: "native-surface".to_string(),
                    severity: severity.to_string(),
                    message: msg,
                    file: args.lockfile.clone(),
                    line: 0,
                    suggestion: None,
                });
            }

            let errors = malicious.len();
            let warnings = surfaces.iter().filter(|s| s.has_proc_macro).count();
            let total = packages.len();
            let passed = total.saturating_sub(errors);

            let output = JsonOutput {
                version: "1.0.0".to_string(),
                timestamp: "2026-09-18T12:00:00Z".to_string(),
                summary: JsonSummary {
                    total,
                    errors,
                    warnings,
                    passed,
                },
                results,
            };

            println!("{}", serde_json::to_string_pretty(&output)?);

            if !malicious.is_empty() && (args.fail_critical || true) {
                std::process::exit(1);
            }
        } else {
            if !malicious.is_empty() {
                eprintln!("⚠️  KNOWN-MALICIOUS PACKAGES DETECTED:");
                for m in &malicious {
                    eprintln!("  BLOCKED: {}@{}", m.name, m.version);
                }
                if args.fail_critical {
                    std::process::exit(1);
                }
            }
        }
    } else if args.watch {
        if is_json {
            eprintln!(r#"{{"error": "Watch mode requires eBPF support"}}"#);
            std::process::exit(2);
        } else {
            eprintln!("Watch mode requires eBPF support (coming in v0.2.0)");
            eprintln!("Use --check for one-shot analysis");
            std::process::exit(2);
        }
    } else {
        if is_json {
            let output = JsonOutput {
                version: "1.0.0".to_string(),
                timestamp: "2026-09-18T12:00:00Z".to_string(),
                summary: JsonSummary {
                    total: 0,
                    errors: 0,
                    warnings: 0,
                    passed: 0,
                },
                results: vec![],
            };
            println!("{}", serde_json::to_string_pretty(&output)?);
        } else {
            println!("sandbox-ffi-layers v{}", env!("CARGO_PKG_VERSION"));
            println!("Use --check to analyze a Cargo.lock, or --watch for runtime monitoring");
        }
    }

    Ok(())
}

